#!/usr/bin/env bash# Definición de colores y constantes de formato# Restablecerexport CRESET="\033[0m"# Estilos de textoexport BOLD="\033[1m"export UNBOLD="\033[21m"export DIM="\033[2m"export UNDIM="\033[22m"export ITALIC="\033[3m"export UNITALIC="\033[23m"export UNDERLINE="\033[4m"export NOUNDERLINE="\033[24m"export BLINK="\033[5m"export UNBLINK="\033[25m"export REVERSE="\033[7m"export UNREVERSE="\033[27m"export HIDDEN="\033[8m"export UNHIDDEN="\033[28m"export STRIKE="\033[9m"export UNSTRIKE="\033[29m"# Colores de textoexport DEFAULT_TEXT="\033[39m"export BLACK="\033[30m"export RED="\033[31m"export GREEN="\033[32m"export YELLOW="\033[33m"export BLUE="\033[34m"export PURPLE="\033[35m"export CYAN="\033[36m"export LIGHT_GRAY="\033[37m"export DARK_GRAY="\033[90m"export LIGHT_RED="\033[91m"export LIGHT_GREEN="\033[92m"export LIGHT_YELLOW="\033[93m"export LIGHT_BLUE="\033[94m"export LIGHT_PURPLE="\033[95m"export LIGHT_CYAN="\033[96m"export WHITE="\033[97m"# Colores de fondoexport BG_DEFAULT="\033[49m"export BG_BLACK="\033[40m"export BG_RED="\033[41m"export BG_GREEN="\033[42m"export BG_YELLOW="\033[43m"export BG_BLUE="\033[44m"export BG_PURPLE="\033[45m"export BG_CYAN="\033[46m"export BG_LIGHT_GRAY="\033[47m"export BG_DARK_GRAY="\033[100m"export BG_LIGHT_RED="\033[101m"export BG_LIGHT_GREEN="\033[102m"export BG_LIGHT_YELLOW="\033[103m"export BG_LIGHT_BLUE="\033[104m"export BG_LIGHT_PURPLE="\033[105m"export BG_LIGHT_CYAN="\033[106m"export BG_WHITE="\033[107m"# Combinaciones comunesexport ERROR_COLOR="${BOLD}${RED}"export WARNING_COLOR="${BOLD}${YELLOW}"export SUCCESS_COLOR="${BOLD}${GREEN}"export INFO_COLOR="${BOLD}${BLUE}"export NOTICE_COLOR="${BOLD}${PURPLE}"export DEBUG_COLOR="${BOLD}${CYAN}"# Formato para URLsexport URL_COLOR="${UNDERLINE}${CYAN}"# Variables de estadoexport IS_COLOR_SUPPORTED=0# Detectar soporte de colorif [ -t 1 ]; then    ncolors=$(tput colors)    if [ -n "$ncolors" ] && [ $ncolors -ge 8 ]; then        IS_COLOR_SUPPORTED=1    fifi# Función para desactivar colores si no hay soportedisable_colors() {    if [ "$IS_COLOR_SUPPORTED" -eq 0 ]; then        CRESET=""        BOLD="" UNBOLD=""        DIM="" UNDIM=""        ITALIC="" UNITALIC=""        UNDERLINE="" NOUNDERLINE=""        BLINK="" UNBLINK=""        REVERSE="" UNREVERSE=""        HIDDEN="" UNHIDDEN=""        STRIKE="" UNSTRIKE=""        DEFAULT_TEXT=""        BLACK="" RED="" GREEN="" YELLOW="" BLUE="" PURPLE="" CYAN="" LIGHT_GRAY=""        DARK_GRAY="" LIGHT_RED="" LIGHT_GREEN="" LIGHT_YELLOW=""        LIGHT_BLUE="" LIGHT_PURPLE="" LIGHT_CYAN="" WHITE=""        BG_DEFAULT=""        BG_BLACK="" BG_RED="" BG_GREEN="" BG_YELLOW="" BG_BLUE="" BG_PURPLE="" BG_CYAN=""        BG_LIGHT_GRAY="" BG_DARK_GRAY="" BG_LIGHT_RED="" BG_LIGHT_GREEN=""        BG_LIGHT_YELLOW="" BG_LIGHT_BLUE="" BG_LIGHT_PURPLE="" BG_LIGHT_CYAN="" BG_WHITE=""        ERROR_COLOR=""        WARNING_COLOR=""        SUCCESS_COLOR=""        INFO_COLOR=""        NOTICE_COLOR=""        DEBUG_COLOR=""        URL_COLOR=""    fi}# Detectar si se está redirigiendo la salidaif [ ! -t 1 ]; then    disable_colorsfi